import{_ as t,l as c,o as e,c as i,v as r,p as l,x as o,d as p,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"cgroups","description":"","frontmatter":{"title":"cgroups","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cgroups.md","filePath":"cs/cgroups.md","lastUpdated":1789023840000}'),u={name:"cs/cgroups.md"};function h(m,a,_,g,f,E){const s=c("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="cgroups" tabindex="-1">cgroups <a class="header-anchor" href="#cgroups" aria-label="Permalink to &quot;cgroups&quot;">​</a></h1><div class="epigraph"><p>控制组把进程放进树里，对 CPU、内存、I/O 等资源记账并施加上限；超限则节流或触发组内 OOM。</p><footer>—— 据 Linux cgroup 文档；Silberschatz 对资源容器的整理</footer></div><p><a href="/cs/namespaces">上一课</a>切开名字，没有切开物理帧与时间片。<a href="/cs/working-set">工作集</a> 与 <a href="/cs/oom-killer">OOM</a> 是全机的。<a href="/cs/timeslice-cfs">调度</a> 可以按组再分权重。缺口是 <strong>cgroup</strong>：可嵌套的进程集合 + 各子系统控制器。v1 多层级与 v2 统一层级合并叙述，不背挂载细节考试。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多租户若只靠 nice，无法保证「这一组最多 2GB、最多 50% CPU」。缺口：进程加入某 cgroup；memory 控制器记账匿名与文件页，超上限则回收该组，再不够则组内 OOM；cpu 控制器给权重或带宽；io 控制器限制 blk-mq 上的比例。接口经 <a href="/cs/sysfs-proc">sysfs</a> 风格的 cgroup 文件系统。</p><p><span class="marginnote">v2 要求进程只在叶子组（简化）。委派让非特权用户管理子树。本课不写如何逃出限制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>创建目录即建组，把 pid 写入 <code>cgroup.procs</code>，写 <code>memory.max</code> 等。内核在缺页、分配、调度选任务时看当前任务的组。与 namespaces 正交：可以只做 cgroup 不做容器，也可以组合。writeback 可以按组节流，接上已有脏页课。</p>',8)),(e(),l(d,null,{default:o(()=>[n(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20G%5B%22cgroup%20%E6%A0%91%22%5D%0A%20%20G%20--%3E%20CPU%5B%22cpu%20%E6%9D%83%E9%87%8D%2F%E9%85%8D%E9%A2%9D%22%5D%0A%20%20G%20--%3E%20MEM%5B%22memory%20%E4%B8%8A%E9%99%90%22%5D%0A%20%20G%20--%3E%20IO%5B%22io%20%E4%B8%8A%E9%99%90%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>cgroup 把负荷控制从「全机抖动」细化到「一组作业的 ΣW」。它不提供独立内核，只提供记账与拒绝/回收。与过度提交同时存在：组内承诺仍可超组上限，于是组内 OOM 先于全机。不要把 Kubernetes 的 YAML 写进 OS 课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每个控制器文件名的清单。不保证实时组与普通组的所有组合有可移植语义。下一课把 ns + cgroup（再加下一课的 syscall 过滤）收成「容器在 OS 里究竟是什么」。</p><p>后课默认：资源可按组封顶。与命名空间合在一起的容器含义，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cgroup 对进程组记账并限制 CPU/内存/IO。</li><li>与 namespaces 正交；组内 OOM 可先于全机。</li><li>容器作为组合抽象是下一课。</li><li>出处：Linux <code>cgroups(7)</code>；Silberschatz et al., <em>OSC</em>。</li></ul>',7))])}const O=t(u,[["render",h]]);export{A as __pageData,O as default};
